SELECT "School Code"
FROM frpm
WHERE "Enrollment (K-12)" + "Enrollment (Ages 5-17)" > 500;

SELECT COUNT(*) AS "count"
FROM "disp"
WHERE "account_id" BETWEEN 1 AND 10;

WITH "carcinogenic_molecules" AS (
    SELECT "molecule"."molecule_id"
    FROM "molecule"
    WHERE "molecule"."label" = '+'
),
"single_bond_count" AS (
    SELECT COALESCE(SUM(
        CASE WHEN "bond"."bond_type" = '-' THEN 1 ELSE 0 END
    ), 0) AS "cnt"
    FROM "bond"
    WHERE "bond"."molecule_id" IN (
        SELECT "molecule_id" FROM "carcinogenic_molecules"
    )
),
"atom_count" AS (
    SELECT COUNT("atom"."atom_id") AS "cnt"
    FROM "atom"
    WHERE "atom"."molecule_id" IN (
        SELECT "molecule_id" FROM "carcinogenic_molecules"
    )
)
SELECT ROUND(
    (SELECT "cnt" FROM "single_bond_count") * 1.0 /
    NULLIF((SELECT "cnt" FROM "atom_count"), 0),
    4
) AS "average";

SELECT ROUND(
    (SELECT COUNT(DISTINCT "molecule_id")
     FROM "bond"
     WHERE "bond_type" = '#'
    ) * 100.0 /
    (SELECT COUNT(DISTINCT "molecule_id")
     FROM (
         SELECT "molecule_id" FROM "atom"
         UNION
         SELECT "molecule_id" FROM "bond"
     )
    ),
    4
) AS "percent_triple_bond_compounds";

-- Calculate the percentage of all molecules that are both carcinogenic (label = '+') and contain at least one hydrogen atom (element = 'h')
SELECT ROUND(
    CAST(
        SUM(
            CASE WHEN m.label = '+' AND EXISTS (
                SELECT 1 FROM atom a 
                WHERE a.molecule_id = m.molecule_id AND a.element = 'h'
            ) THEN 1 ELSE 0 END
        ) AS REAL
    ) * 100.0 / COUNT(m.molecule_id),
    4
) AS percentage
FROM molecule m;

SELECT ROUND(
    CAST(SUM(CASE WHEN T1.label = '+' AND EXISTS (SELECT 1 FROM atom WHERE atom.molecule_id = T1.molecule_id AND atom.element = 'cl') THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*),
    4
) AS percentage
FROM molecule AS T1;

